// The manifest is generated by scripts/fetch-photos.mjs before dev/build.
// Order follows the Immich album, so curation happens entirely in Immich.
import manifest from "../data/photos.json";

export interface Photo {
  id: string;
  src: string;
  width: number | null;
  height: number | null;
  description: string | null;
  takenAt: string | null;
}

export const photos: Photo[] = manifest as Photo[];
